import React,
{
useState
}
from "react";

import Navbar
from "../../components/Navbar";

import Sidebar
from "../../components/Sidebar";

import {
calculateEMI,
totalRepayment,
totalInterest
}
from "../../utils/calculators";

function EmiCalculator(){

const [principal,
setPrincipal]
=
useState("");

const [rate,
setRate]
=
useState("");

const [months,
setMonths]
=
useState("");

const [emi,
setEmi]
=
useState("");

const [repayment,
setRepayment]
=
useState("");

const [interest,
setInterest]
=
useState("");

const calculate =
()=>{

const emiValue =
calculateEMI(

parseFloat(principal),

parseFloat(rate),

parseInt(months)

);

const total =
totalRepayment(
emiValue,
months
);

const totalInt =
totalInterest(
principal,
total
);

setEmi(
emiValue
);

setRepayment(
total
);

setInterest(
totalInt
);

};

return(

<div>

<Navbar/>

<div className="d-flex">

<Sidebar/>

<div className="container p-4">

<div className="card">

<div className="card-header">

EMI Calculator

</div>

<div className="card-body">

<div className="form-group">

<label>

Loan Amount

</label>

<input
type="number"
className="form-control"
value={principal}
onChange={(e)=>
setPrincipal(
e.target.value
)
}
/>

</div>

<div className="form-group">

<label>

Interest Rate %

</label>

<input
type="number"
className="form-control"
value={rate}
onChange={(e)=>
setRate(
e.target.value
)
}
/>

</div>

<div className="form-group">

<label>

Tenure Months

</label>

<input
type="number"
className="form-control"
value={months}
onChange={(e)=>
setMonths(
e.target.value
)
}
/>

</div>

<button
className=
"btn btn-success"
onClick={
calculate
}
>

Calculate EMI

</button>

{
emi &&
<div
className=
"alert alert-success mt-4"
>

<h5>
Monthly EMI :
₹{emi}
</h5>

<h5>
Total Repayment :
₹{repayment}
</h5>

<h5>
Total Interest :
₹{interest}
</h5>

</div>
}

</div>

</div>

</div>

</div>

</div>

);

}

export default EmiCalculator;
